// Add or remove RSS feeds here. Region is derived from the article domain in 'Format Message'.
const feeds = [
  { url: 'https://search.cnbc.com/rs/search/combinedcms/view.xml?partnerId=wrss01&id=10000664' }, // US
  { url: 'https://finance.yahoo.com/news/rssindex' },                                              // US
  { url: 'https://feeds.bbci.co.uk/news/business/rss.xml' },                                       // London
  { url: 'https://www.theguardian.com/business/rss' },                                             // London
  { url: 'https://asia.nikkei.com/rss/feed/nar' },                                                 // Asia
  { url: 'https://www.straitstimes.com/news/business/rss.xml' },                                   // Asia
];
return feeds.map(f => ({ json: f }));

// domain suffix -> region. Extend this map when you add feeds.
const MAP = {
  'cnbc.com': 'US', 'yahoo.com': 'US',
  'bbc.co.uk': 'LONDON', 'bbc.com': 'LONDON', 'theguardian.com': 'LONDON',
  'nikkei.com': 'ASIA', 'straitstimes.com': 'ASIA',
};
const regionOf = link => {
  try { const h = new URL(link).hostname; for (const k in MAP) if (h.endsWith(k)) return MAP[k]; } catch (e) {}
  return 'OTHER';
};
const HOURS = Number($env.NEWS_LOOKBACK_HOURS || 3.25);   // look-back window; set NEWS_LOOKBACK_HOURS=8 for 4 runs/day
const cutoff = Date.now() - HOURS * 3600 * 1000;
const PER_REGION = 4;
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const buckets = { US: [], LONDON: [], ASIA: [], OTHER: [] };
const seen = new Set();
for (const it of $input.all()) {
  const j = it.json;
  if (!j.title || !j.link || seen.has(j.link)) continue;   // skips failed feeds too
  seen.add(j.link);
  const t = Date.parse(j.isoDate || j.pubDate || '');
  if (!isNaN(t) && t < cutoff) continue;                   // too old
  buckets[regionOf(j.link)].push({ title: j.title, link: j.link, t: isNaN(t) ? 0 : t });
}
const heads = { US: '🇺🇸 <b>US</b>', LONDON: '🇬🇧 <b>London / Europe</b>', ASIA: '🌏 <b>Asia</b>' };
const now = new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata', hour12: false });
let text = `🌍 <b>Global Markets News</b> — ${now} IST`;
for (const r of ['US', 'LONDON', 'ASIA']) {
  const list = buckets[r].sort((a, b) => b.t - a.t).slice(0, PER_REGION);
  text += `\n\n${heads[r]}\n` + (list.length
    ? list.map(x => `• <a href="${esc(x.link)}">${esc(x.title)}</a>`).join('\n')
    : '• no new headlines in this window');
}
return [{ json: { text } }];
